/* @autogenerated */
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';
import { Theme } from 'app/features/template/theme/model/theme.model';
import { ThemeRepository } from 'app/features/template/theme/repository/theme-repository.service';
import { Component, inject } from '@angular/core';

@Component({ selector: 'theme-view-disable-action', standalone: false, template: '' })
export class ThemeViewDisableActionComponent extends ConfirmAction<Theme> {
  readonly name = 'disable';
  protected readonly scope = 'template/theme';
  protected readonly repository = inject(ThemeRepository);

  protected override appliesTo(items: Theme[]) {
    return items.every((item) => !!item.enabled) && true;
  }
  protected execute([item]: Theme[]) {
    return this.repository.disable(item.uid);
  }
}
